    }

    @Override
    public Class<? extends C> getContainerClass() {
        return this.universalRecipeTransferHandler.getContainerClass();
    }

    @Override
    public Optional<MenuType<C>> getMenuType() {
        return this.universalRecipeTransferHandler.getMenuType();
    }

    @Override
